// React
import React, { Component } from "react";
import { Link } from "react-router-dom";
import { FormattedMessage } from "react-intl";

// Redux
import { fetchAffiliate, updateAffiliate, createAffiliate, fetchAffiliates } from "../../actions/affiliates";
import { connect } from "react-redux";
import AddAffiliateComponent from "./addAffiliate";
import UpdateAffiliateComponent from "./updateAffiliate";

// components
import { Card, CardBody, CardHeader, Col, Row, Button, Alert } from "reactstrap";

class Affiliates2 extends Component {
	constructor (props) {
		super(props);
		this.state = {
			showModal                        : false,
			processorCreated                 : false,
			showUpdateModal                  : false,
			createSuccessAlertVisible        : true,
			updateSuccessAlertVisible        : true,
			updateProcessorErrorAlertVisible : true,
			createProcessorErrorAlertVisible : true,
			activePage                       : 1,
			hasError                         : false,
			defaultHiddenColumnNames         : [ "sex", "car" ],
			cardType                         : [
				{ name: "Debit", value: "Debit" },
				{ name: "Credit", value: "Credit" },
			],
		};
		this.onDismissCreateSuccessAlert = this.onDismissCreateSuccessAlert.bind(this);
		this.onDismissUpdateSuccessAlert = this.onDismissUpdateSuccessAlert.bind(this);
		this.onDismissUpdateProcessorErrorAlert = this.onDismissUpdateProcessorErrorAlert.bind(this);
		this.onDismisscreateProcessorErrorAlert = this.onDismisscreateProcessorErrorAlert.bind(this);
	}
	local = "";
	componentDidMount = () => {
		this.props.fetchAffiliates();
	};

	clearNotifications = () => {
		this.props.affiliates.affiliateCreated = null;
		this.props.affiliates.affiliateUpdated = null;
	};
	componentWillUnmount () {
		this.clearNotifications();
	}

	onDismissCreateSuccessAlert () {
		this.setState({ createSuccessAlertVisible: false });
	}

	onDismissUpdateSuccessAlert () {
		this.setState({ updateSuccessAlertVisible: false });
	}

	onDismissUpdateProcessorErrorAlert () {
		this.setState({ updateProcessorErrorAlertVisible: false });
	}

	onDismisscreateProcessorErrorAlert () {}
	onSubmit = (values) => {
		this.props.createAffiliate(values);
		this.closeModal();
	};

	updateAffiliate = (id) => {
		this.clearNotifications();
		this.setState({ showUpdateModal: !this.state.showUpdateModal });
		this.props.fetchAffiliate(id);
	};

	closeUpdateModal = () => {
		this.setState({ showUpdateModal: !this.state.showUpdateModal });
	};

	onSubmitUpdate = (values) => {
		this.props.updateAffiliate(values);
		this.closeUpdateModal();
	};
	toggle = () => {
		this.setState({ showModal: !this.state.showModal });
		this.clearNotifications();
	};
	closeModal = () => {
		this.setState({ showModal: !this.state.showModal });
	};
	deleteProcessor = (id) => {
		this.props.deleteProcessor(id);
	};

	render () {
		console.log("AFFILIATES 2", this.props);
		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						{this.props.affiliates.affiliateCreated ? (
							<Alert
								color='success'
								isOpen={this.state.createSuccessAlertVisible}
								toggle={this.onDismissCreateSuccessAlert}
							>
								<FormattedMessage
									id='Success: Affiliate Added Successfully!'
									defaultMessage='Success: Affiliate Added Successfully!'
								/>
							</Alert>
						) : null}

						{this.props.affiliates.affiliateUpdated ? (
							<Alert
								color='success'
								isOpen={this.state.updateSuccessAlertVisible}
								toggle={this.onDismissUpdateSuccessAlert}
							>
								<FormattedMessage
									id='Success: Affiliate Updated Successfully!'
									defaultMessage='Success: Affiliate Updated Successfully!'
								/>
							</Alert>
						) : null}

						<Card>
							<CardHeader>
								<FormattedMessage id='Affiliates' defaultMessage='Affiliates' />
								<Button
									className={"float-right mb-0"}
									style={{ marginBottom: "20px" }}
									color='success'
									onClick={this.toggle}
								>
									<i className='fa fa-plus' />&nbsp;{" "}
									<FormattedMessage id='Add Affiliate' defaultMessage='Add Affiliate' />
								</Button>
							</CardHeader>
							<CardBody>
								<Row>
									{this.props.affiliateListUnPaginated ? (
										[
											this.props.affiliateListUnPaginated.length > 0 ? this.props
												.affiliateListUnPaginated ? (
												this.props.affiliateListUnPaginated.map((item, index) => (
													<Col style={{ display: "flex", flexDirection: "column" }} md='2'>
														<i
															className={"flag-icon flag-icon-" + item.code.toLowerCase()}
															title='al'
															id='al'
															style={{ fontSize: "7.5rem" }}
														/>

														<Link
															style={{ cursor: "pointer" }}
															to={"/configuration/affiliates/" + item.code + "/details"}
														>
															<h6 style={{ textAlign: "center", paddingTop: "10px" }}>
																{item.name.toUpperCase()}
															</h6>
														</Link>
														<h6 style={{ textAlign: "center" }}>
															CODE: {item.code.toUpperCase()}
														</h6>
													</Col>
												))
											) : (
												<tr key='1'>
													<td colSpan='4'>
														<p className='text-center text-danger'>
															<FormattedMessage
																id='There are no affiliates created at the moment'
																defaultMessage='There are no affiliates created at the moment.'
															/>
														</p>
													</td>
												</tr>
											) : (
												<tr key='1'>
													<td colSpan='4'>
														<p className='text-center text-danger'>
															<FormattedMessage
																id='There are no affiliates created at the moment'
																defaultMessage='There are no affiliates created at the moment.'
															/>
														</p>
													</td>
												</tr>
											),
										]
									) : (
										[ "" ]
									)}
								</Row>
							</CardBody>
						</Card>
					</Col>
				</Row>

				<AddAffiliateComponent
					{...this.state}
					{...this.toggle}
					onSubmit={this.onSubmit}
					closeModal={this.closeModal}
					{...this.props}
				/>
				<UpdateAffiliateComponent
					{...this.state}
					{...this.updateToggle}
					closeUpdateModal={this.closeUpdateModal}
					onSubmit={this.onSubmitUpdate}
					{...this.props}
				/>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		affiliates               : state.affiliates,
		affiliateListUnPaginated : state.affiliates.affiliateListUnPaginated,
		initialValues            : state.affiliates.affiliate,
	};
};

export default connect(mapStateToProps, {
	fetchAffiliate,
	createAffiliate,
	updateAffiliate,
	fetchAffiliates,
})(Affiliates2);
